const nowdt=()=>new Date(Date.now()-new Date().getTimezoneOffset()*6e4).toISOString().slice(0,16);
function mig(){db.s.forEach(x=>{if(!x.pid){let p=db.p.find(q=>q.dossier==(x.h.dossier||'')&&q.nom==(x.h.projet||'Projet'));if(!p){p={id:'p'+Math.random().toString(36).slice(2),nom:x.h.projet||'Projet',dossier:x.h.dossier||'',commune:x.h.commune||'',charge:x.h.charge||'',foreur:x.h.foreur||'',preleveur:x.h.preleveur||'',methode:x.h.methode||''};db.p.push(p)}x.pid=p.id}})}mig();
