document.addEventListener('keydown',e=>{if(e.key=='Enter'&&e.target.dataset.code!=null){e.preventDefault();addC(+e.target.dataset.code,e.target.value)}});
document.addEventListener('click',e=>{const t=e.target.closest('[data-act]');if(!t)return;const a=t.dataset.act,i=+t.dataset.i,j=+t.dataset.j,s=cur();
if(a=='new'){const P=db.p.find(x=>x.id==db.cp),n=db.s.filter(x=>x.pid==P.id).length,id='s'+Date.now();db.s.push({id,pid:P.id,h:{projet:P.nom,dossier:P.dossier,commune:P.commune,charge:P.charge,foreur:P.foreur,preleveur:P.preleveur,methode:P.methode,labo:P.labo,conf:P.conf,prep:P.prep,meth:P.meth,cond:P.cond,cons:P.cons,num:'S'+(n+1),debut:nowdt()},L:[],S:[]});db.cur=id;db.tab='h'}
else if(a=='dup'){const o=db.s.find(x=>x.id==t.dataset.v),P=db.p.find(x=>x.id==o.pid),n=db.s.filter(x=>x.pid==o.pid).length,id='s'+Date.now(),L=JSON.parse(JSON.stringify(o.L));L.forEach(l=>l.pid='');db.s.push({id,pid:o.pid,h:{...o.h,projet:P.nom,dossier:P.dossier,commune:P.commune,charge:P.charge,num:'S'+(n+1),debut:nowdt(),fin:'',nsi:'',nss:'',loc:'',x:'',y:'',z:'',lat:'',lon:'',acc:'',meteo:'',remarques:'',envoi:'',pidamb:'',pzns:'',prof:''},L,S:[]});db.cur=id;db.cp=o.pid;db.tab='h';toast('Dupliqué : lithologies copiées. PID, coordonnées, niveaux et échantillons vides.')}
else if(a=='newP'){const id='p'+Date.now();db.p.push({id,nom:'Nouveau projet',dossier:'',commune:'',charge:'',foreur:'',preleveur:'',methode:''});db.cp=id;window._d=0}
else if(a=='openP'){db.cp=t.dataset.v;window._d=0}
else if(a=='open'){db.cur=t.dataset.v;db.tab='h'}
else if(a=='imp'){doImport($('#imp').value);return}
else if(a=='exall'){shJson('releves-sol_'+new Date().toISOString().slice(0,10)+'.json',exp(db.p,db.s));return}
else if(a=='exp'){const P=db.p.find(x=>x.id==db.cp);shJson(('projet_'+(P.dossier||P.nom||'x')+'.json').replace(/[^\w.\-]+/g,'_'),exp([P],db.s.filter(x=>x.pid==P.id)));return}
else if(a=='fv'){toast('Préparation de la fiche…');ficheFond(s).then(showFiche);return}
else if(a=='cv'){carteFond(db.p.find(x=>x.id==db.cp)).then(showFiche);return}
else if(a=='cpdf'||a=='cjpg'){ficheOut(a=='cpdf'?'pdf':'jpg',db.p.find(x=>x.id==db.cp));return}
else if(a=='fpdf'){ficheOut('pdf');return}
else if(a=='fjpg'){ficheOut('jpg');return}
else if(a=='fclose'){const v=$('#fv');v&&v.remove();return}
else if(a=='fprint'){try{window.print()}catch(e){toast('Impression indisponible ici')}return}
else if(a=='opt'){const P=db.p.find(x=>x.id==db.cp),g=t.dataset.r=='P'?P:s&&s.h;if(g){const k=t.dataset.k,v=t.dataset.v,ar=g[k]||[],has=ar.includes(v);g.u=Date.now();g[k]=t.dataset.m=='1'?(has?ar.filter(y=>y!=v):[...ar,v]):(has?[]:[v])}}
else if(a=='delPh'){const arr=t.dataset.k=='s'?s.ph:s.S[i].ph,x=arr.splice(j,1)[0];if(x)idbOp('del',x.id)}
else if(a=='shph'){shPh(s);return}
else if(a=='gps'){if(!navigator.geolocation)return toast('GPS indisponible');toast('Acquisition GPS…');navigator.geolocation.getCurrentPosition(p=>{const c=p.coords,[X,Y]=l93(c.latitude,c.longitude);Object.assign(s.h,{x:String(Math.round(X)),y:String(Math.round(Y)),lat:c.latitude.toFixed(6),lon:c.longitude.toFixed(6),acc:String(Math.round(c.accuracy))});save();render();toast('Position enregistrée (±'+Math.round(c.accuracy)+' m)')},e=>toast('GPS refusé ou indisponible : '+e.message),{enableHighAccuracy:true,timeout:25000,maximumAge:0});return}
else if(a=='idx'){db.cur=null;db.cp=null;window._d=0}
else if(a=='delP'){if(window._d){db.s.filter(x=>x.pid==db.cp).forEach(x=>phIds(x).forEach(id=>idbOp('del',id)));db.s=db.s.filter(x=>x.pid!=db.cp);db.p=db.p.filter(x=>x.id!=db.cp);db.cp=null;window._d=0}else window._d=1}
else if(a=='home'){db.cur=null;window._d=0}else if(a=='tab')db.tab=t.dataset.v;
else if(a=='del'){if(window._d){phIds(s).forEach(id=>idbOp('del',id));db.s=db.s.filter(x=>x!==s);db.cur=null;window._d=0}else window._d=1}
else if(a=='addL'){const l=s.L[s.L.length-1];s.L.push({from:l?l.to:'0',to:'',lit:'remblai',desc:'',obs:'',pid:''})}
else if(a=='delL')s.L.splice(i,1);
else if(a=='addS'){const x=s.S[s.S.length-1];s.S.push({from:x?x.to:'',to:'',heure:now(),name:'',an:[],codes:[]})}
else if(a=='delS'){(s.S[i].ph||[]).forEach(p=>idbOp('del',p.id));s.S.splice(i,1)}
else if(a=='an'){const k=s.S[i].an,v=t.dataset.v;k.includes(v)?k.splice(k.indexOf(v),1):k.push(v)}
else if(a=='addC'){return addC(i,$('#c'+i).value)}else if(a=='delC')s.S[i].codes.splice(j,1);
else if(a=='scan')return scan(i);else if(a=='stop')return stop();
else if(a=='copy'){const el=$('#'+t.dataset.v);el.select();(navigator.clipboard?navigator.clipboard.writeText(el.value):Promise.reject()).then(()=>toast('Copié'),()=>{try{document.execCommand('copy');toast('Copié')}catch(x){toast('Sélection faite : copier manuellement')}});return}
else if(a=='share'){const v=$('#cs').value;navigator.share?navigator.share({title:'Relevé '+(s.h.num||''),text:v}).catch(()=>{}):toast('Partage indisponible : utiliser Copier');return}
else if(a=='imp'){try{let d=JSON.parse($('#imp').value);if(Array.isArray(d))d={p:[],s:d};if(!Array.isArray(d.s))throw 0;(d.p||[]).forEach(x=>{if(!db.p.find(y=>y.id==x.id))db.p.push(x)});d.s.forEach(x=>{if(!db.s.find(y=>y.id==x.id))db.s.push(x)});mig();toast('Importé')}catch(x){return toast('JSON invalide')}}
save();render()});
render();
